      { s: "", jp: "{参加費|さんかひ}はフル{八千円|はっせんえん}、ハーフ{六千円|ろくせんえん}、{十|じゅっ}キロ{四千円|よんせんえん}です。{高校生|こうこうせい}{以下|いか}は{半額|はんがく}になります。", ro: "Sankahi wa furu hassen'en, hāfu rokusen'en, jukkiro yonsen'en desu. Kōkōsei ika wa hangaku ni narimasu.", en: "The entry fee is 8,000 yen for full, 6,000 for half and 4,000 for 10 km. Students up to high school pay half." },
      { s: "", jp: "{申|もう}し{込|こ}みは{九月|くがつ}{三十日|さんじゅうにち}まで、インターネットのみで{受|う}け{付|つ}けます。", ro: "Mōshikomi wa kugatsu sanjūnichi made, intānetto nomi de uketsukemasu.", en: "Applications are accepted only on the internet, until September 30." },
      { s: "", jp: "{支払|しはら}いはクレジットカードか、コンビニで{行|おこな}えます。コンビニ{払|ばら}いは{別|べつ}に{百円|ひゃくえん}かかります。", ro: "Shiharai wa kurejittokādo ka, konbini de okonaemasu. Konbini barai wa betsu ni hyakuenkakarimasu.", en: "Payment can be made by credit card or at a convenience store. Payment at a convenience store costs an extra 100 yen." },
      { s: "", jp: "{申|もう}し{込|こ}み{後|ご}の{取|と}り{消|け}しはできず、{参加費|さんかひ}も{返金|へんきん}されません。ただし、{大会|たいかい}が{中止|ちゅうし}になった{場合|ばあい}は{全額|ぜんがく}{返金|へんきん}します。", ro: "Mōshikomi go no torikeshi wa dekizu, sankahi mo henkin saremasen. Tadashi, taikai ga chūshi ni natta baai wa zengaku henkin shimasu.", en: "Cancellation after applying is not possible and the fee is not refunded. However, if the event is cancelled, the full amount is refunded." },
      { s: "", jp: "{大会|たいかい}{当日|とうじつ}は、{午前|ごぜん}{七時|しちじ}から{受付|うけつけ}を{行|おこな}います。みぶんしょうを{忘|わす}れずにお{持|も}ちください。", ro: "Taikai tōjitsu wa, gozen shichiji kara uketsuke o okonaimasu. Mibunshō o wasurezu ni omochi kudasai.", en: "On the day of the event, reception opens at 7 a.m. Please remember to bring identification." },
      { s: "", jp: "{荷物|にもつ}は{会場|かいじょう}の{預|あず}かり{所|じょ}でむりょうで{預|あず}かります。", ro: "Nimotsu wa kaijō no azukari jo de muryō de azukarimasu.", en: "Luggage will be kept free of charge at the venue's cloakroom." },
      { s: "", jp: "{給水所|きゅうすいじょ}は{五|ご}キロごとに{設|もう}けられます。", ro: "Kyūsuijo wa go kirogo to ni mōkeraremasu.", en: "Water stations will be set up every 5 km." },
      { s: "", jp: "{制限|せいげん}{時間|じかん}はフルが{六時間|ろくじかん}、ハーフが{三時間|さんじかん}、{十|じゅっ}キロが{九十分|きゅうじゅっぷん}です。", ro: "Seigen jikan wa furu ga rokujikan, hāfu ga sanjikan, jukkiro ga kyūjuppun desu.", en: "The time limits are six hours for full, three hours for half and 90 minutes for 10 km." }
